<div class="page-heading"><div><span class="eyebrow">Administración</span><h1>Usuarios</h1><p>Accesos y roles del entorno.</p></div><button class="btn btn-primary" data-modal-open="user-create">＋ Usuario</button></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><section class="card"><div class="table-wrap"><table class="modern-table"><thead><tr><th>Usuario</th><th>Correo</th><th>Roles</th><th>Estado</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['nombres'].' '.$u['apellidos'])?></td><td><?=e($u['email'])?></td><td><?=e($u['roles']??'—')?></td><td><?=$u['activo']?'Activo':'Inactivo'?></td></tr><?php endforeach;?></tbody></table></div></section><div class="modal" id="user-create"><div class="modal-backdrop"></div><div class="modal-dialog"><div class="modal-header"><h2>Nuevo usuario</h2><button class="modal-close" data-modal-close>×</button></div><form method="POST" action="<?=url('/admin/usuarios')?>"><?=csrf_field()?><div class="modal-body form-grid"><label><span>Nombres</span><input name="nombres" required></label><label><span>Apellidos</span><input name="apellidos" required></label><label class="field-full"><span>Email</span><input type="email" name="email" required></label><label><span>Teléfono</span><input name="telefono"></label><label><span>Rol</span><select name="rol_id"><option value="">Sin rol</option><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=e($r['nombre'])?></option><?php endforeach;?></select></label></div><div class="modal-footer"><button class="btn btn-primary">Crear</button></div></form></div></div>
